breach.segment:
// Breach: at least 10% of the zone's VMs AND at least 2 VMs under pressure.
// Lower pressured_instances to 1 for small fleets; raise thresholds for node pools designed to run memory-full (for example Kubernetes nodes).
WHERE pressured_pct >= 10 AND pressured_instances >= 2
| KEEP resource.attributes.project_id, resource.attributes.zone, pressured_pct, pressured_instances, instances, max_mem_used_pct, max_swap_in_bps, pressured_instance_names
| SORT pressured_pct DESC
| LIMIT 50
